      reconcileStaleClaimedVideoReservations(),
      reconcileStaleClaimedAgentStreamReservations(),
    ]);
    console.info('[CostControl] Reconciled stale reservations', { expired, reconciledVideoClaims, reconciledAgentStreamClaims });
  },
);

