    async buildContext(signal?: AbortSignal): Promise<PipelineContext> {
        const preparation = new ContextPreparation(signal);
        // 1. Fetch State (The "Working Context")
        const stateContext = await preparation.wait('working context', () => this.resolver.resolveContext());

        // 2. Fetch History (The "Session")
        const { view: chatHistoryString, historicalSummary, historyWarning } = await preparation.wait('conversation history', () => this.historyManager.getCompiledHistory(signal));

        // 3. Big Brain Auto-Recall (Unified across all 4 layers)
        const { useStore } = await preparation.wait('context store', () => importWithRetry(() => import('@/core/store')));
        const { isKnowledgeBaseEnabled, userProfile } = useStore.getState();
        const userId = userProfile?.uid || auth.currentUser?.uid;

        let autoRecallBlock = '';
        let relevantMemories: string[] = [];
        let userAlignmentRules: string[] = [];

        if (userId && isKnowledgeBaseEnabled) {
            try {
                // Extract the user's latest message for intent matching
                const recentContext = this.extractRecentContext(chatHistoryString);

                // Determine active agent ID
                const agentId = stateContext.activeModule || 'generalist';

                // Assemble context from all 4 layers in parallel
                const bigBrainContext = await preparation.wait('memory recall', () => bigBrainEngine.assembleContext(
                    userId,
                    agentId,
                    recentContext,
                    stateContext.projectId
                ));

                // Format into XML block for prompt injection
                autoRecallBlock = bigBrainEngine.formatForPrompt(bigBrainContext);

                // Extract individual components for backward compatibility
                userAlignmentRules = bigBrainContext.alignmentRules;

                // Also keep the relevantMemories array for the legacy formatMemoryContext
                if (bigBrainContext.episodicRecall) {
                    relevantMemories = bigBrainContext.episodicRecall
                        .split('\n')
                        .filter(l => l.startsWith('- '))
                        .map(l => l.substring(2));
                }

                logger.debug(
                    `[ContextPipeline] BigBrain injected ${bigBrainContext.totalCharacters} chars ` +
                    `(vault:${bigBrainContext.meta.vaultFactCount}, ` +
                    `episodic:${bigBrainContext.meta.episodicMatches}, ` +
                    `rules:${bigBrainContext.meta.alignmentRuleCount})`
                );
            } catch (err: unknown) {
                preparation.throwIfStopped();
                logger.warn('[ContextPipeline] BigBrain assembly failed (non-blocking):', err);
                // Fallback: still try to get basic memories
                relevantMemories = await preparation.wait('fallback memories', () => this.fallbackRetrieveMemories(stateContext.projectId, chatHistoryString));
            }
        } else if (isKnowledgeBaseEnabled) {
            // No user but knowledge base enabled — basic memory retrieval
            relevantMemories = await preparation.wait('fallback memories', () => this.fallbackRetrieveMemories(stateContext.projectId, chatHistoryString));
        }

        // 4. Fetch Active Living Plans (V2 Continuity)
    async assembleContext(
        userId: string,
        agentId: string,
        userMessage: string,
        _projectId?: string
    ): Promise<BigBrainContext> {
        if (this.isE2EMode) {
            return {
                dailyLog: '',
                vaultFacts: '',
                episodicRecall: '',
                alignmentRules: [],
                totalCharacters: 0,
                meta: {
                    dailyLogEntries: 0,
                    vaultFactCount: 0,
                    episodicMatches: 0,
                    alignmentRuleCount: 0,
                    layerErrors: [],
                }
            };
        }

        const meta = {
            dailyLogEntries: 0,
            vaultFactCount: 0,
            episodicMatches: 0,
            alignmentRuleCount: 0,
            layerErrors: [] as string[],
        };

        const budgets = {
            dailyLog: Math.floor(this.config.maxTotalCharacters * this.config.budgetAllocation.dailyLog),
            vaultFacts: Math.floor(this.config.maxTotalCharacters * this.config.budgetAllocation.vaultFacts),
            episodicRecall: Math.floor(this.config.maxTotalCharacters * this.config.budgetAllocation.episodicRecall),
            alignmentRules: Math.floor(this.config.maxTotalCharacters * this.config.budgetAllocation.alignmentRules),
        };

        // Run all 4 layers in parallel — non-blocking
        const [dailyLog, vaultFacts, episodicRecall, alignmentRules] = await Promise.allSettled([
            this.fetchDailyLog(userId, budgets.dailyLog),
            this.fetchVaultFacts(userId, agentId, budgets.vaultFacts),
            this.fetchEpisodicRecall(userId, userMessage, budgets.episodicRecall),
            this.fetchAlignmentRules(userId, userMessage, budgets.alignmentRules),
        ]);

        // Extract results or handle failures
        const dailyLogResult = dailyLog.status === 'fulfilled' ? dailyLog.value : '';
        const vaultFactsResult = vaultFacts.status === 'fulfilled' ? vaultFacts.value : '';
        const episodicRecallResult = episodicRecall.status === 'fulfilled' ? episodicRecall.value : '';
        const alignmentRulesResult = alignmentRules.status === 'fulfilled' ? alignmentRules.value : [];

        // Log failures
        if (dailyLog.status === 'rejected') meta.layerErrors.push(`dailyLog: ${dailyLog.reason}`);
        if (vaultFacts.status === 'rejected') meta.layerErrors.push(`vaultFacts: ${vaultFacts.reason}`);
        if (episodicRecall.status === 'rejected') meta.layerErrors.push(`episodicRecall: ${episodicRecall.reason}`);
        if (alignmentRules.status === 'rejected') meta.layerErrors.push(`alignmentRules: ${alignmentRules.reason}`);

        if (meta.layerErrors.length > 0) {
            logger.warn('[BigBrain] Layer errors:', meta.layerErrors);
        }

        // Count metadata
        meta.dailyLogEntries = dailyLogResult ? dailyLogResult.split('\n').length : 0;
        meta.vaultFactCount = vaultFactsResult ? vaultFactsResult.split('\n').filter(l => l.startsWith('-')).length : 0;
        meta.episodicMatches = episodicRecallResult ? episodicRecallResult.split('\n').filter(l => l.startsWith('-')).length : 0;
        meta.alignmentRuleCount = alignmentRulesResult.length;

        const totalCharacters = dailyLogResult.length + vaultFactsResult.length +
            episodicRecallResult.length + alignmentRulesResult.join('').length;

        logger.debug(
            `[BigBrain] Assembled context: ${totalCharacters} chars ` +
            `(log:${meta.dailyLogEntries}, vault:${meta.vaultFactCount}, ` +
            `episodic:${meta.episodicMatches}, rules:${meta.alignmentRuleCount})`
        );

        return {
            dailyLog: dailyLogResult,
            vaultFacts: vaultFactsResult,
            episodicRecall: episodicRecallResult,
            alignmentRules: alignmentRulesResult,
            totalCharacters,
            meta,
        };
    }

    /**
     * Format the assembled context into a single XML block for prompt injection.
     */

